def scorpion(x=985, y=52, scale=0.7, mirror=True, fill="currentColor"):
    sx = -scale if mirror else scale
    p = {k: "".join(v) for k, v in PATHS.items()}
    return (
        f'<g transform="translate({x},{y}) scale({sx},{scale})" fill="{fill}" fill-rule="evenodd">'
        '<g>\n'
        f'<g><path d="{p["legs-bottom"]}"/>'
        '<animateTransform attributeName="transform" type="rotate" '
        'values="0 337 149;3.2 337 149;-0.5 337 149;-3.4 337 149;0 337 149" dur="1.6s" repeatCount="indefinite"/></g>\n'
        f'<g><path d="{p["legs-top"]}"/>'
        '<animateTransform attributeName="transform" type="rotate" '
        'values="0 337 149;-3.4 337 149;0.5 337 149;3.2 337 149;0 337 149" dur="1.6s" repeatCount="indefinite"/></g>\n'
        '<g><animateTransform attributeName="transform" type="rotate" '
        'values="0 212 142;-17 212 142;0 212 142;-17 212 142;0 212 142" dur="4.4s" repeatCount="indefinite"/>\n'
        f'<path d="{p["tail-base"]}"/>'
        '<g transform="translate(106 160.5)"><g>'
        '<animateTransform attributeName="transform" type="scale" '
        f'values="{TIP_SCALE}" dur="4.4s" repeatCount="indefinite"/>'
        f'<path transform="translate(-106 -160.5)" d="{p["tail-tip"]}"/></g></g></g>\n'
        '</g></g>'
    )

TIP_SCALE = "1 1;0.8 1;0.58 1;0.8 1;1 1"